use std::collections::HashMap;
use std::error::Error;
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug, PartialEq)]
enum LineError {
    MissingEquals,
    EmptyKey,
    BadValue(ParseIntError),
}

impl From<ParseIntError> for LineError {
    fn from(e: ParseIntError) -> Self {
        LineError::BadValue(e)
    }
}

impl fmt::Display for LineError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            LineError::MissingEquals => write!(f, "no '=' in the line"),
            LineError::EmptyKey => write!(f, "the key is empty"),
            LineError::BadValue(_) => write!(f, "the value is not a whole number"),
        }
    }
}

impl Error for LineError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            LineError::BadValue(e) => Some(e),
            _ => None,
        }
    }
}

#[derive(Debug, PartialEq)]
struct ConfigError {
    line: usize,
    kind: LineError,
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "line {}: {}", self.line, self.kind)
    }
}

impl Error for ConfigError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        Some(&self.kind)
    }
}

fn parse_line(line: &str) -> Result<(String, i64), LineError> {
    let (key, value) = line.split_once('=').ok_or(LineError::MissingEquals)?;
    let key = key.trim();
    if key.is_empty() {
        return Err(LineError::EmptyKey);
    }
    let n: i64 = value.trim().parse()?;
    Ok((key.to_string(), n))
}

fn parse_config(text: &str) -> Result<HashMap<String, i64>, ConfigError> {
    let mut out = HashMap::new();
    for (i, raw) in text.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (k, v) = parse_line(line).map_err(|kind| ConfigError { line: i + 1, kind })?;
        out.insert(k, v);
    }
    Ok(out)
}

unitTests:
use std::error::Error;

test("a good file", || {
    let c = parse_config("# sizes\nwidth = 800\n\n height=600 \n").unwrap();
    check_eq(c.len(), 2);
    check_eq(c["width"], 800);
    check_eq(c["height"], 600);
});

test("line numbers and kinds", || {
    let e = parse_config("a = 1\nnothing here\n").unwrap_err();
    check_eq(e.line, 2);
    check_eq(&e.kind, &LineError::MissingEquals);
    check_eq(e.to_string(), "line 2: no '=' in the line");
    check_eq(parse_config(" = 5").unwrap_err().to_string(), "line 1: the key is empty");
});

test("the cause chain", || {
    let e = parse_config("a = 1\nb = 2\nc = lots").unwrap_err();
    check_eq(e.to_string(), "line 3: the value is not a whole number");
    let first = e.source().expect("a ConfigError has a source");
    check_eq(first.to_string(), "the value is not a whole number");
    let second = first.source().expect("BadValue has a source");
    check_eq(second.to_string(), "invalid digit found in string");
    check(second.source().is_none());
});

